css:
/* Modales (Login & Perfil B2B) */
.saas-modal-overlay { position: fixed; inset: 0; background: rgba(10, 34, 64, 0.6); backdrop-filter: blur(5px); z-index: 3000; display: flex; align-items: center; justify-content: center; padding: 20px; opacity: 1; transition: opacity 0.3s ease; }
.saas-modal-overlay.hidden { opacity: 0; pointer-events: none; }
.saas-modal-card { background: #FFFFFF; width: 100%; max-width: 440px; border-radius: 24px; padding: 40px; box-shadow: 0 25px 50px -12px rgba(0,0,0,0.25); position: relative; transform: translateY(0); transition: transform 0.4s cubic-bezier(0.16, 1, 0.3, 1); border: 1px solid #E2E8F0; }
.saas-modal-overlay.hidden .saas-modal-card { transform: translateY(30px); }

.close-modal-btn { position: absolute; top: 20px; right: 20px; background: transparent; border: none; font-size: 1.8rem; color: #94a3b8; cursor: pointer; transition: color 0.2s; line-height: 1; width: 30px; height: 30px; display: flex; align-items: center; justify-content: center; border-radius: 50%; }
.close-modal-btn:hover { color: #A81200; background: #fef2f2; }

/* Login Modal */
.modal-header-center { text-align: center; margin-bottom: 20px; }
.modal-logo-clean { height: 75px; margin-bottom: 15px; object-fit: contain; }
.modal-header-center h2 { font-size: 1.8rem; font-weight: 900; color: #0A2240; margin-bottom: 10px; letter-spacing: -0.5px; }
.modal-header-center p { font-size: 0.95rem; color: #64748B; line-height: 1.5; }
.secure-badge { display: flex; justify-content: center; align-items: center; gap: 6px; margin-top: 25px; font-size: 0.8rem; color: #94a3b8; font-weight: 600; }
.secure-badge svg { width: 14px; height: 14px; }

/* Perfil B2B Modal */
.profile-card { max-width: 480px; padding: 0; overflow: hidden;}
.profile-header { background: #f8fafc; padding: 30px; display: flex; align-items: center; gap: 20px; border-bottom: 1px solid #E2E8F0; }
.profile-avatar-img { width: 64px; height: 64px; border-radius: 50%; object-fit: cover; box-shadow: 0 4px 10px rgba(10,34,64,0.1); border: 2px solid #FFFFFF; background: #E2E8F0;}
.profile-info h2 { font-size: 1.25rem; font-weight: 800; color: #0F172A; margin-bottom: 2px; line-height: 1.2; word-break: break-word;}
.user-email { font-size: 0.9rem; color: #64748b; font-weight: 500; }

.reorder-section { padding: 30px; }
.reorder-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 15px; }
.reorder-header h3 { font-size: 1.05rem; font-weight: 800; color: #0A2240; text-transform: uppercase; }

.order-list-preview { background: #f8fafc; border: 1px solid #E2E8F0; border-radius: 12px; padding: 15px 20px; margin-bottom: 25px; }
.order-list-preview ul { list-style: none; display: flex; flex-direction: column; gap: 8px; padding: 0; margin: 0; }
.order-list-preview li { display: flex; align-items: center; gap: 8px; font-size: 0.95rem; color: #0F172A; font-weight: 500; }
.order-list-preview li svg { width: 16px; color: #10b981; }

.logout-wrapper { padding: 0 30px 25px; display: flex; justify-content: center; }
.btn-logout { background: transparent; border: none; color: #94a3b8; font-size: 0.9rem; font-weight: 600; cursor: pointer; text-decoration: underline; transition: color 0.2s;}
.btn-logout:hover { color: #A81200; }

/* Icono Navbar Logueado Global */
.icon-btn.logged-in { border-color: #25D366 !important; background: rgba(37, 211, 102, 0.1) !important; position: relative; }
.icon-btn.logged-in::after { content: ''; position: absolute; top: 0px; right: 0px; width: 12px; height: 12px; background: #25D366; border-radius: 50%; border: 2px solid #16365C; z-index: 2;}
.nav-user-avatar { width: 100%; height: 100%; object-fit: cover; border-radius: 50%; display: none; }
.icon-btn.logged-in .nav-user-avatar { display: block; }
.icon-btn.logged-in svg { display: none; }

/* Toasts Globales */
.toast-container { position: fixed; bottom: 100px; left: 50%; transform: translateX(-50%); z-index: 3000; display: flex; flex-direction: column; gap: 10px; pointer-events: none; }
.toast { background: rgba(10, 34, 64, 0.95); backdrop-filter: blur(10px); color: #FFFFFF; padding: 14px 28px; border-radius: 50px; font-size: 0.95rem; font-weight: 600; box-shadow: 0 10px 30px rgba(0,0,0,0.3); display: flex; align-items: center; gap: 12px; animation: toastSlideUp 0.3s ease forwards; border: 1px solid rgba(255,255,255,0.1); }
.toast svg { width: 20px; color: #25D366; }
.toast.fade-out { animation: toastFadeOut 0.4s ease forwards; }
@keyframes toastSlideUp { from { opacity: 0; transform: translateY(30px) scale(0.9); } to { opacity: 1; transform: translateY(0) scale(1); } }
@keyframes toastFadeOut { to { opacity: 0; transform: translateY(-15px) scale(0.9); } }


/* =========================================
   1. VARIABLES Y BASE ELITE
   ========================================= */
:root {
    --zarco-blue: #0A2240; 
    --zarco-red: #A81200; 

    --color-blanco: #FFFFFF;
    --bg-dashboard: #F4F7F9; /* Fondo limpio B2B */
    --border-soft: #CBD5E1; /* Gris de línea un poco más definido pero suave */
    --text-main: #0F172A;
    --text-muted: #64748B;

    --bezier-smooth: cubic-bezier(0.4, 0, 0.2, 1);
    --expo: cubic-bezier(0.16, 1, 0.3, 1); 
}

* { margin: 0; padding: 0; box-sizing: border-box; -webkit-tap-highlight-color: transparent; }
html { scroll-behavior: smooth; }

body.bg-dashboard { 
    font-family: 'Inter', sans-serif; 
    color: var(--text-main); 
    background-color: var(--bg-dashboard); 
    line-height: 1.6; 
    -webkit-font-smoothing: antialiased;
}

.text-red { color: var(--zarco-red) !important; }

/* =========================================
   2. REVEAL ENGINE FLUIDO
   ========================================= */
.reveal-up { 
    opacity: 0; 
    transform: translateY(30px); 
    transition: opacity 1s var(--expo), transform 1s var(--expo); 
}
.reveal-up.active { 
    opacity: 1; 
    transform: translateY(0); 
}
.stagger-1 { transition-delay: 0.1s; } 
.stagger-2 { transition-delay: 0.2s; } 

/* =========================================
   3. GUÍA COMERCIAL (Estructura Dividida)
   ========================================= */
.zarco-guide-section {
    padding-top: 270px; 
    padding-bottom: 120px;
    padding-left: 5%;
    padding-right: 5%;
    max-width: 1350px;
    margin: 0 auto;
}

.zarco-guide-grid {
    display: grid;
    grid-template-columns: 1fr 1.5fr; 
    gap: 80px;
    align-items: start; 
}

/* COLUMNA IZQUIERDA (Sticky Perfect) */
.zarco-guide-sticky {
    position: sticky;
    top: 140px; 
}

.zarco-sticky-content {
    position: relative;
}

.zarco-label {
    display: inline-block;
    font-size: 0.75rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 2px;
    color: var(--zarco-red);
    margin-bottom: 20px;
    position: relative;
    padding-left: 35px;
}
.zarco-label::before {
    content: '';
    position: absolute;
    left: 0;
    top: 50%;
    width: 20px;
    height: 1px;
    background-color: var(--zarco-red);
}

.zarco-hero-title {
    font-family: 'Inter', sans-serif;
    font-size: clamp(2.5rem, 4vw, 3.5rem); 
    font-weight: 900;
    line-height: 1.1;
    letter-spacing: -1px;
    color: var(--zarco-blue);
    margin-bottom: 20px;
}

.zarco-hero-copy {
    font-family: 'Inter', sans-serif;
    font-size: 1.15rem;
    font-weight: 400;
    line-height: 1.6;
    color: var(--text-muted);
    max-width: 750px;
    margin: 0 auto 25px auto;
}

.zarco-signature {
    font-family: 'Playfair Display', serif;
    font-size: 1.15rem;
    color: var(--zarco-red);
    font-style: italic;
    font-weight: 700;
    margin-top: 10px;
}

/* =========================================
   4. COLUMNA DERECHA (Lista Editorial - SIN CUADROS)
   ========================================= */
.zarco-guide-feed {
    border-top: 1px solid var(--border-soft); /* Solo la línea superior del bloque */
    display: flex;
    flex-direction: column;
}

.zarco-article {
    /* CERO fondos, CERO sombras, CERO bordes laterales */
    background: transparent;
    border-bottom: 1px solid var(--border-soft);
}

.zarco-article__header {
    width: 100%;
    background: none;
    border: none;
    padding: 35px 0; /* Sin padding a los lados para que fluya natural */
    cursor: pointer;
    text-align: left;
    display: flex;
    flex-direction: column;
    gap: 12px;
}

/* Hover súper sutil solo en el texto, NO en cajas */
.zarco-article__header:hover .zarco-article__title {
    color: var(--zarco-red);
}

.zarco-article__meta {
    display: flex;
    align-items: center;
    gap: 15px;
}

.zarco-number {
    font-family: 'Playfair Display', serif;
    font-style: italic;
    font-size: 1.2rem;
    color: var(--text-muted);
    opacity: 0.6;
    transition: color 0.3s ease;
}

.zarco-category {
    font-size: 0.7rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 1.5px;
    color: var(--text-muted);
}

.zarco-article__title-wrap {
    display: flex;
    justify-content: space-between;
    align-items: center;
    width: 100%;
    gap: 20px;
}

.zarco-article__title {
    font-size: clamp(1.2rem, 2vw, 1.4rem);
    font-weight: 700;
    line-height: 1.3;
    letter-spacing: -0.3px;
    color: var(--text-main);
    transition: color var(--transition-fast);
}

/* CRUZ FINA ANIMADA */
.zarco-icon-cross {
    position: relative;
    width: 18px;
    height: 18px;
    flex-shrink: 0;
}
.zarco-icon-cross::before, 
.zarco-icon-cross::after {
    content: '';
    position: absolute;
    background-color: var(--text-muted);
    transition: transform 0.4s var(--expo), background-color var(--transition-fast);
}
.zarco-icon-cross::before { top: 8.5px; left: 0; width: 18px; height: 1.5px; }
.zarco-icon-cross::after { top: 0; left: 8.5px; width: 1.5px; height: 18px; }

/* CAJÓN DESPLEGABLE (Bug de altura arreglado) */
.zarco-article__drawer {
    max-height: 0;
    overflow: hidden;
    /* Quitamos el opacity:0 para evitar bugs visuales de desaparición, manejamos solo la altura */
    transition: max-height 0.6s var(--expo);
}

.zarco-article__content {
    padding: 0 0 40px 0; /* Padding interno solo abajo, sin padding lateral */
    max-width: 680px;
}

.zarco-lead {
    font-size: 1.1rem;
    font-weight: 600;
    line-height: 1.5;
    color: var(--zarco-blue);
    margin-bottom: 20px;
}

.zarco-article__content p {
    font-size: 0.95rem;
    font-weight: 400;
    line-height: 1.7;
    color: var(--text-muted);
    margin-bottom: 16px;
}

.zarco-quote {
    font-family: 'Playfair Display', serif;
    font-size: 1.35rem;
    font-style: italic;
    line-height: 1.4;
    color: var(--zarco-blue);
    margin: 30px 0;
    padding-left: 20px;
    border-left: 1.5px solid var(--zarco-red);
}

/* CTAs MICRO-ELEGANTES */
.zarco-action-link {
    display: inline-flex;
    align-items: center;
    margin-top: 15px;
    font-size: 0.8rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 1.5px;
    color: var(--zarco-blue);
    text-decoration: none;
    transition: color var(--transition-fast);
}

.zarco-action-link span {
    margin-left: 8px;
    font-size: 1.1rem;
    transition: transform var(--transition-fast);
}

.zarco-action-link:hover { color: var(--zarco-red); }
.zarco-action-link:hover span { transform: translateX(6px); }

/* =========================================
   5. ESTADOS ACTIVOS
   ========================================= */
.zarco-article.is-active .zarco-number { color: var(--zarco-red); opacity: 1; }
.zarco-article.is-active .zarco-article__title { color: var(--zarco-red); }
.zarco-article.is-active .zarco-icon-cross { transform: rotate(135deg); }
.zarco-article.is-active .zarco-icon-cross::before, 
.zarco-article.is-active .zarco-icon-cross::after { background-color: var(--zarco-red); }

/* =========================================
   6. MÓVIL (Centrado Perfecto de Columna Izq)
   ========================================= */
@media (max-width: 992px) {
    .zarco-guide-section { padding-top: 180px; padding-left: 20px; padding-right: 20px; }
    .zarco-guide-grid {
        grid-template-columns: 1fr; 
        gap: 50px;
    }

    .zarco-guide-sticky { position: relative; top: 0; }

    /* Centrado exacto que pediste */
    .zarco-sticky-content {
        display: flex;
        flex-direction: column;
        align-items: center;
        text-align: center;
    }

    .zarco-label { padding-left: 0; }
    .zarco-label::before { display: none; }
    .zarco-hero-copy { text-align: center; }

    .zarco-article__header { padding: 25px 0; }
    .zarco-article__content { padding: 0 0 30px 0; }
    .zarco-icon-cross { display: none; }
}


  :root {
    --zarco-blue: #0A2240;
    --zarco-blue-light: #16365C;
    --zarco-blue-glass: rgba(10,34,64,0.95);
    --zarco-red: #A81200;
    --white: #FFFFFF;
    --wa-green: #10B981;
    --transition-fast: 0.3s cubic-bezier(0.16,1,0.3,1);
    --shadow-pop: 0 15px 35px -5px rgba(10,34,64,0.15),0 5px 15px rgba(0,0,0,0.05)
  }
  .desktop-only { display: block }
  .mobile-only { display: none }
  .navbar {
    position: fixed;
    top: 0;
    width: 100%;
    z-index: 2000;
    transition: transform .6s var(--transition-fast),box-shadow .6s var(--transition-fast);
    box-shadow: 0 4px 20px rgba(0,0,0,.15);
    font-family: 'Inter',sans-serif
  }
  .navbar.nav-hidden { transform: translateY(-100%) }
  .nav-container {
    width: 90%;
    max-width: 1400px;
    margin: 0 auto;
    position: relative
  }
  .nav-top {
    background-color: var(--zarco-blue-light);
    padding: 20px 0;
    transition: padding var(--transition-fast)
  }
  .top-container {
    display: grid;
    grid-template-columns: 1fr auto 1fr;
    align-items: center;
    max-width: 1200px;
    margin: 0 auto
  }
  .nav-left { justify-self: start }
  .nav-center { justify-self: center }
  .nav-right {
    justify-self: end;
    display: flex;
    align-items: center;
    gap: 15px
  }
  .nav-logo img {
    height: 100px;
    filter: drop-shadow(0 4px 10px rgba(0,0,0,.3));
    transition: height var(--transition-fast);
    display: block
  }
  .nav-logo img:hover { transform: scale(1.03) }
  .nav-gif {
    height: 100px;
    object-fit: contain;
    border-radius: 8px;
    display: block;
    filter: drop-shadow(0 4px 10px rgba(0,0,0,.2))
  }
  .btn-primary {
    background-color: var(--zarco-red);
    color: var(--white);
    border: none;
    padding: 14px 32px;
    font-weight: 900;
    font-size: .85rem;
    text-transform: uppercase;
    letter-spacing: 2px;
    cursor: pointer;
    border-radius: 6px;
    transition: all var(--transition-fast);
    position: relative;
    overflow: hidden;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 8px
  }
  .btn-primary:hover {
    transform: translateY(-3px);
    box-shadow: 0 8px 25px rgba(168,18,0,.4);
    background-color: #ba1400
  }
  .nav-bottom {
    background-color: var(--zarco-blue);
    height: 45px;
    display: flex;
    align-items: center;
    justify-content: center;
    position: relative
  }
  .bottom-container {
    display: flex;
    justify-content: center;
    align-items: center;
    width: 100%;
    position: static
  }
  .nav-menu {
    display: flex;
    list-style: none;
    gap: 4rem;
    margin: 0 auto;
    align-items: center;
    position: static;
    padding: 0
  }
  .nav-link {
    color: rgba(255,255,255,.85);
    text-decoration: none;
    font-weight: 700;
    font-size: .8rem;
    letter-spacing: 2.5px;
    position: relative;
    padding: 12px 0;
    transition: color var(--transition-fast);
    display: flex;
    align-items: center;
    gap: 6px;
    text-transform: uppercase
  }
  .nav-link:hover, .nav-link.active { color: var(--white) }
  .nav-link::after {
    content: '';
    position: absolute;
    width: 0;
    height: 3px;
    bottom: 0;
    left: 50%;
    transform: translateX(-50%);
    background-color: var(--zarco-red);
    transition: width var(--transition-fast);
    border-radius: 2px 2px 0 0
  }
  .nav-link:hover::after, .nav-link.active::after { width: 100% }
  .nav-link svg {
    width: 14px;
    height: 14px;
    transition: transform var(--transition-fast);
    vertical-align: middle;
    margin-top: -1px
  }
  .has-dropdown { position: static }
  .dropdown-menu {
    position: absolute;
    top: 100%;
    left: 0;
    right: 0;
    width: 100vw;
    height: 55px;
    background-color: rgba(22,54,92,.85);
    backdrop-filter: blur(8px);
    display: flex;
    justify-content: center;
    align-items: center;
    gap: 4rem;
    list-style: none;
    padding: 0;
    margin: 0;
    opacity: 0;
    visibility: hidden;
    transform: translateY(-5px);
    transition: all var(--transition-fast);
    box-shadow: 0 10px 20px rgba(0,0,0,.1);
    z-index: 1999;
    border-top: 1px solid rgba(255,255,255,.05)
  }
  .has-dropdown:hover .dropdown-menu {
    opacity: 1;
    visibility: visible;
    transform: translateY(0)
  }
  .has-dropdown:hover .nav-link svg { transform: rotate(180deg) }
  .dropdown-link {
    display: inline-block;
    color: rgba(255,255,255,.85);
    text-decoration: none;
    font-size: .8rem;
    font-weight: 700;
    letter-spacing: 2px;
    padding: 12px 0;
    position: relative;
    transition: color var(--transition-fast)
  }
  .dropdown-link:hover { color: var(--white) }
  .dropdown-link::after {
    content: '';
    position: absolute;
    width: 0;
    height: 2px;
    bottom: 0;
    left: 50%;
    transform: translateX(-50%);
    background-color: var(--zarco-red);
    transition: width var(--transition-fast)
  }
  .dropdown-link:hover::after { width: 100% }
  .navbar.scrolled .nav-top { padding: 10px 0 }
  .navbar.scrolled .nav-logo img, .navbar.scrolled .nav-gif { height: 60px }
  .user-menu-wrapper { position: relative }
  .user-trigger {
    background: transparent;
    border: 1.5px solid rgba(255,255,255,.3);
    width: 44px;
    height: 44px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    transition: all .3s ease;
    padding: 0;
    position: relative
  }
  .user-trigger:hover {
    border-color: var(--white);
    background: rgba(255,255,255,.1);
    transform: translateY(-2px)
  }
  .user-trigger svg.default-icon {
    width: 20px;
    height: 20px;
    color: var(--white);
    transition: transform .3s ease
  }
  .user-trigger:hover svg.default-icon { transform: scale(1.1) }
  .user-trigger.logged-in {
    border-color: transparent;
    padding: 2px;
    background: linear-gradient(135deg,#10B981,#059669)
  }
  .user-trigger.logged-in:hover {
    transform: translateY(-2px);
    box-shadow: 0 4px 12px rgba(16,185,129,.3)
  }
  .nav-avatar-img {
    width: 100%;
    height: 100%;
    border-radius: 50%;
    object-fit: cover;
    border: 2px solid var(--zarco-blue-light);
    display: none;
    background: #fff
  }
  .user-trigger.logged-in .nav-avatar-img { display: block }
  .user-trigger.logged-in svg.default-icon { display: none }
  .online-dot {
    position: absolute;
    bottom: -2px;
    right: -2px;
    width: 12px;
    height: 12px;
    background: var(--wa-green);
    border: 2px solid var(--zarco-blue-light);
    border-radius: 50%;
    display: none
  }
  .user-trigger.logged-in .online-dot { display: block }
  .user-popover {
    position: absolute;
    top: calc(100% + 15px);
    right: 0;
    width: 280px;
    background: var(--white);
    border-radius: 16px;
    box-shadow: var(--shadow-pop);
    border: 1px solid #E2E8F0;
    opacity: 0;
    visibility: hidden;
    transform: translateY(-10px);
    transition: all var(--transition-fast);
    z-index: 2005
  }
  .user-popover.active {
    opacity: 1;
    visibility: visible;
    transform: translateY(0)
  }
  .user-popover::before {
    content: '';
    position: absolute;
    top: -6px;
    right: 20px;
    width: 12px;
    height: 12px;
    background: var(--white);
    transform: rotate(45deg);
    border-left: 1px solid #E2E8F0;
    border-top: 1px solid #E2E8F0
  }
  .popover-header {
    padding: 20px;
    border-bottom: 1px solid #F1F5F9;
    text-align: left
  }
  .popover-name {
    display: block;
    font-size: 1.05rem;
    font-weight: 800;
    color: var(--zarco-blue);
    margin-bottom: 2px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis
  }
  .popover-email {
    display: block;
    font-size: .8rem;
    color: #64748B;
    font-weight: 500;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis
  }
  .popover-body {
    padding: 10px;
    display: flex;
    flex-direction: column;
    gap: 5px
  }
  .popover-link {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 12px 15px;
    border-radius: 10px;
    text-decoration: none;
    color: #0F172A;
