/* 1. VARIABLES GLOBALES (Por si acaso el componente carga aislado) */
:root {
    --zarco-blue: #0A2240; 
    --zarco-red: #A81200; 
    --zarco-red-dark: #7A0A00; 
    --white: #FFFFFF; 
    --wa-green: #25D366; 
    --wa-green-dark: #1DA851;
    --transition-fast: 0.3s cubic-bezier(0.4, 0, 0.2, 1);
    --expo: cubic-bezier(0.16, 1, 0.3, 1);
}

/* 2. MOTOR DE ANIMACIÓN (REVEAL) */
.reveal-up { opacity: 0; transform: translateY(30px); transition: opacity 1s var(--expo), transform 1s var(--expo); }
.reveal-up.active { opacity: 1; transform: translateY(0); }
.reveal { opacity: 0; transform: translateY(20px); transition: opacity 0.8s ease, transform 0.8s ease; }
.reveal.active { opacity: 1; transform: translateY(0); }

/* Animación propia para el botón flotante */
@keyframes floatPop {
    0% { opacity: 0; transform: translateY(30px) scale(0.8); }
    100% { opacity: 1; transform: translateY(0) scale(1); }
}

/* 3. ESTILOS DEL FOOTER B2B PREMIUM */
.master-footer { 
    background: linear-gradient(135deg, var(--zarco-red) 0%, var(--zarco-red-dark) 100%); 
    color: var(--white); 
    padding: 80px 0 0; 
    position: relative; 
