document.addEventListener('DOMContentLoaded', () => {

    // --- 1. LÓGICA DE ACORDEÓN ---
    const articles = document.querySelectorAll('.zarco-article');

    articles.forEach(article => {
        const header = article.querySelector('.zarco-article__header');
        const drawer = article.querySelector('.zarco-article__drawer');

        header.addEventListener('click', () => {
            const isActive = article.classList.contains('is-active');

            // Cierra el resto suavemente
            articles.forEach(a => {
                a.classList.remove('is-active');
                a.querySelector('.zarco-article__header').setAttribute('aria-expanded', 'false');
                a.querySelector('.zarco-article__drawer').style.maxHeight = null;
            });

            // Abre el seleccionado (Añadimos 60px de holgura de seguridad para el texto)
            if (!isActive) {
                article.classList.add('is-active');
                header.setAttribute('aria-expanded', 'true');
                drawer.style.maxHeight = (drawer.scrollHeight + 60) + "px";
            }
        });
    });

    // --- 2. REVEAL ENGINE (Animaciones al hacer scroll) ---
    const revealOptions = {
        threshold: 0.1, 
        rootMargin: "0px 0px -50px 0px"
    };

    const revealOnScroll = new IntersectionObserver(function(entries, observer) {
        entries.forEach(entry => {
            if (!entry.isIntersecting) {
                return;
            } else {
                entry.target.classList.add('active'); 
                observer.unobserve(entry.target); 
            }
        });
    }, revealOptions);

    const elementsToReveal = document.querySelectorAll('.reveal-up');
    elementsToReveal.forEach(el => {
        revealOnScroll.observe(el);
    });

});
